using System.Collections.Concurrent;
using SpstKniznica.Common.Text;

namespace EmailService.Templating;

/// <summary>
/// Loads react-email HTML from <c>Templates/*.html</c> (generated by
/// <c>web/npm run emails:build</c>) and substitutes escaped tokens.
/// </summary>
public sealed class LoanEmailHtmlRenderer(IHostEnvironment env, ILogger<LoanEmailHtmlRenderer> logger)
{
    private readonly ConcurrentDictionary<string, string> _cache = new(StringComparer.Ordinal);

    public string? TryRender(string templateKey, IReadOnlyDictionary<string, string> values)
    {
        var html = LoadTemplate(templateKey);
        if (html is null)
        {
            return null;
        }

        foreach (var (key, raw) in values)
        {
            html = html.Replace(
                "{{" + key + "}}",
                HtmlSafety.Encode(raw),
                StringComparison.Ordinal);
        }

        if (!HtmlSafety.IsSafeHtmlFragment(html))
        {
            logger.LogWarning("Rendered template {TemplateKey} failed HTML safety check", templateKey);
            return null;
        }

        return html;
    }

    private string? LoadTemplate(string templateKey)
    {
        if (_cache.TryGetValue(templateKey, out var cached))
        {
            return cached;
        }

        var fileName = templateKey switch
        {
            "loan-borrowed" => "loan-borrowed.html",
            "loan-returned" => "loan-returned.html",
            "loan-due-reminder" => "loan-due-reminder.html",
            "waitlist-promotion" => "waitlist-promotion.html",
            _ => null,
        };

        if (fileName is null)
        {
            return null;
        }

        foreach (var root in CandidateRoots())
        {
            var path = Path.Combine(root, fileName);
            if (!File.Exists(path))
            {
                continue;
            }

            var text = File.ReadAllText(path);
            _cache[templateKey] = text;
            return text;
        }

        logger.LogWarning(
            "Email HTML template {File} not found under Templates/. Run: cd web && npm run emails:build",
            fileName);
        return null;
    }

    private IEnumerable<string> CandidateRoots()
    {
        yield return Path.Combine(env.ContentRootPath, "Templates");
        yield return Path.Combine(AppContext.BaseDirectory, "Templates");
    }
}
